/* ===================== GENERATED GAMES (from content already in this app) ===================== */
const GEN = [];
const clean = s => String(s || "").trim();
// 1) Clinical Sort from Disease Comparisons
(window.COMPARE || []).forEach(c => {
  if (!c.names || c.names.length < 2 || c.names.length > 3 || !c.rows) return;
  const labels = c.sys === "pharm" ? (window.CMP_DRUG_ROWS || []) : (window.CMP_ROWS || []);
  const keep = c.sys === "pharm" ? ["How it works", "Main uses", "Key adverse effects", "Antidote or reversal", "Most important difference"] : ["Pathophysiology", "Hallmark findings", "Key assessment clues", "Relevant labs/tests", "Medications/treatments", "Dangerous complications", "Most important difference"];
  const items = [];
  c.rows.forEach((row, ri) => {
    const lab = labels[ri]; if (!keep.includes(lab)) return;
    const cells = row.map(clean); if (new Set(cells.map(x => x.toLowerCase())).size !== cells.length) return;
    cells.forEach((cell, ci) => { if (cell.length < 4 || cell.length > 150 || /^(same|as above|—|-|n\/a|none)/i.test(cell)) return; items.push({ t: lab + ": " + cell, c: ci, why: lab + " of " + c.names[ci] + "." }); });
  });
  if (items.length < 6) return;
  const comp = c.rows[(c.sys === "pharm" ? labels.indexOf("Key adverse effects") : labels.indexOf("Dangerous complications"))] || [];
  GEN.push({ id: "cmp-" + c.id, type: "sort", subj: c.sys, topic: c.names.join(" vs "), level: "I", gen: true, round: Math.min(8, items.length),
    hy: ["renal", "endo", "cv", "mat"].includes(c.sys),
    title: "Sort it: " + c.names.join(" vs "),
    intro: "Sort each feature into the condition or drug it belongs to.",
    cats: c.names.slice(), items,
    concept: "Telling " + c.names.join(" from ") + " apart by their cues.",
    safety: comp.length ? "Watch for: " + c.names.map((n, i) => n + " — " + clean(comp[i])).join("; ") + "." : "Know which finding signals danger in each.",
    hesi: clean(c.hesi) || "Look-alike conditions are tested by asking which finding fits which condition.",
    src: ["Disease Comparisons in this app (built from your course files)"] });
});
// 2) Antidote match from the antidote rapid cards
const adPairs = (window.CARDS || []).filter(c => c.cat === "Drug Antidotes and Reversal Agents" && /→/.test(c.topic)).map(c => { const [a, b] = c.topic.split("→").map(clean); return { a, b, why: clean(c.remember) }; }).filter(p => p.a && p.b);
if (adPairs.length >= 6) GEN.push({ id: "gen-antidotes", type: "match", subj: "pharm", topic: "Antidotes", level: "B", gen: true, hy: true, round: 6,
  title: "Antidote match: drug or toxin → reversal agent", aLabel: "Drug or toxin", bLabel: "Antidote", intro: "Match each drug or toxin to its antidote.",
  pairs: adPairs, concept: "Antidote and reversal agent pairs.", safety: "Some poisonings have no antidote (aspirin, lithium) — supportive care and removal.",
  hesi: "Antidote pairs are among the most-tested pharmacology facts.", src: ["Antidote rapid cards in this app (antidotes lesson sources)"] });
// 3) Drug card games by group: generic → trade name, generic → class
const GROUPS = { Cardiovascular: "cv", Endocrine: "endo", Neuro: "neuro", Psych: "psych", Renal: "renal", "Anti-infective": "pharm", OB: "mat", GI: "gi" };
Object.keys(GROUPS).forEach(cls => {
  const meds = (window.MEDS || []).filter(m => m.cls === cls);
  const br = meds.filter(m => m.b && m.b !== "—" && m.b.length < 40).map(m => ({ a: m.g, b: m.b, why: m.g + " is sold as " + m.b + (m.c ? " (" + m.c + ")." : ".") }));
  if (br.length >= 5) GEN.push({ id: "gen-brand-" + slugify(cls), type: "match", subj: GROUPS[cls], topic: cls + " drug names", level: "B", gen: true, round: 6,
    title: cls + " drugs: generic ↔ trade name", aLabel: "Generic", bLabel: "Trade name", intro: "Match each generic name to its trade name.", pairs: br,
    concept: "Recognizing drugs by either name.", safety: "Orders and labels may use either name; confirm both to avoid duplicate dosing.",
    hesi: "Exam stems usually use generic names; trade names help you recognize drugs in practice.", src: ["Drug cards in this app"] });
  const cl = meds.filter(m => m.c && m.c.length < 70).map(m => ({ a: m.g, b: m.c, why: clean(m.mech) ? m.g + ": " + clean(m.mech) + "." : "" }));
  if (cl.length >= 5) GEN.push({ id: "gen-class-" + slugify(cls), type: "match", subj: GROUPS[cls], topic: cls + " drug classes", level: "B", gen: true, round: 6,
    title: cls + " drugs: drug → class", aLabel: "Drug", bLabel: "Class", intro: "Match each drug to its class.", pairs: cl,
    concept: "Drug classes predict actions, side effects, and nursing checks.", safety: "Knowing the class tells you what to assess before giving it.",
    hesi: "Class recognition (by suffix and use) lets you reason about unfamiliar drugs.", src: ["Drug cards in this app"] });
});
// 4) Lab normal ranges
const labPairs = (window.LABS || []).filter(l => l.r && l.r.length < 46 && l.pop !== "Newborn").map(l => ({ a: l.n, b: l.r, why: (l.m ? l.m + ". " : "") + (l.act ? "Nurse: " + l.act : "") }));
if (labPairs.length >= 6) GEN.push({ id: "gen-labs", type: "match", subj: "fund", topic: "Lab values", level: "B", gen: true, hy: true, round: 6,
  title: "Lab test and its adult reference range", aLabel: "Lab test", bLabel: "Typical adult range", intro: "Match each lab to its typical adult range (ranges vary by lab — use the one in the question).",
  pairs: labPairs, concept: "Recognizing normal ranges to spot abnormal results.", safety: "A value inside the range can still matter if it changed fast.",
  hesi: "Lab items give a value and ask what to do; knowing the range is step one.", src: ["Laboratory Values in this app"] });
function slugify(s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""); }

window.GAMES = G.concat(GEN);
window.GAME_SUBJ = { fund: "Fundamentals and infection control", lead: "Leadership and delegation", psych: "Psychiatric and mental health", neuro: "Neurological", endo: "Endocrine", mat: "Maternal and newborn", peds: "Pediatrics", resp: "Respiratory", heme: "Hematology", integ: "Integumentary", renal: "Renal and urinary", cv: "Cardiovascular", gi: "Gastrointestinal", msk: "Musculoskeletal", pharm: "Pharmacology", pain: "Pain", repro: "Reproductive" };
